// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // fuzz the callee selector that the helper will use and a boolean deciding whether the helper should revert
    function testFuzz_property(bool shouldRevert) public {
        // Deploy a helper that will either revert on call or succeed, controlled by shouldRevert.
        // This helper's behavior is the adversarial external party: low-level call may succeed or revert.
        CalleeHelper helper = new CalleeHelper(shouldRevert);

        // Call c.forward(...) and record whether it returns or reverts
        bool ok;
        try c.forward(address(helper), "") {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: the reference contract forwards the callee's success: ok == !shouldRevert
        // The mutant flips the observed result and will violate this for the case when shouldRevert == false
        assertTrue(ok == (!shouldRevert));
    }
}

// Helper that either reverts on any call (simulating a failing callee) or accepts it
contract CalleeHelper {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    fallback() external payable {
        if (shouldRevert) revert("reverting helper");
    }
    receive() external payable {
        if (shouldRevert) revert("reverting helper");
    }
}
